@dataclass
class Particle:
    position: np.ndarray
    velocity: np.ndarray
    mass: float
    acceleration: float

    @property
    def density(self) -> float:
        return self.mass / self.volume

    @property
    def volume(self) -> float:
        return np.prod(self.position.shape)

    def update(self, dt: float):
        self.velocity += self.acceleration * dt
        self.position += self.velocity * dt

    def move(self, dx: float, dy: float, dz: float) -> None:
        self.position += np.array([dx, dy, dz])

    def gravity_force(self) -> float:
        return -G * self.mass * np.sum(self.position) / self.volume

    def viscous_force(self) -> float:
        return -10 * self.density * self.velocity.dot(self.velocity)

class ParticleSystem:
    def __init__(self, particles: List[Particle]):
        self.particles = particles
        self.dt = 0.01
        self.gravity_strength = 1.0
        self.viscosity = 1.0

    def update(self, dt: float):
        for particle in self.particles:
            particle.update(self.dt)

    def move(self, dx: float, dy: float, dz: float):
        for particle in self.particles:
            particle.move(dx, dy, dz)

        self.gravity_force(self.particles)
        self.viscous_force(self.particles)

