        } catch (Exception e) {
            System.out.println("Failed to parse XML file");
            e.printStackTrace();
            return;
        }

        NodeList nodes = (NodeList) XPath.compile("//uiSelector").evaluate(document, XPathConstants.NODESET);
        for (int i = 0; i < nodes.getLength(); i++) {
            Node node = nodes.item(i);
            String selectorName = node.getAttributes().getNamedItem("name").getTextContent();
